package com.nexuspc.order.dto;
import com.nexuspc.order.*; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public record OrderResponse(Long id,String orderNumber,Long customerId,String customerName,String customerEmail,String customerPhone,List<Item> items,Address shippingAddress,String deliveryMethod,BigDecimal deliveryCharge,String paymentMethod,String paymentStatus,String status,BigDecimal subtotal,BigDecimal discount,BigDecimal total,String couponCode,String notes,String paymentUrl,Instant createdAt,Instant updatedAt){
 public record Item(Long productId,String name,String brand,String image,BigDecimal price,int quantity,BigDecimal subtotal){} public record Address(String name,String email,String phone,String division,String district,String area,String address){}
 public static OrderResponse from(Order o){return new OrderResponse(o.getId(),o.getOrderNumber(),o.getUser().getId(),o.getCustomerName(),o.getCustomerEmail(),o.getCustomerPhone(),o.getItems().stream().map(i->new Item(i.getProductId(),i.getName(),i.getBrand(),i.getImage(),i.getPrice(),i.getQuantity(),i.getSubtotal())).toList(),new Address(o.getShippingName(),o.getShippingEmail(),o.getShippingPhone(),o.getDivision(),o.getDistrict(),o.getArea(),o.getShippingAddress()),o.getDeliveryMethod(),o.getDeliveryCharge(),o.getPaymentMethod(),o.getPaymentStatus(),o.getStatus(),o.getSubtotal(),o.getDiscount(),o.getTotal(),o.getCouponCode(),o.getNotes(),null,o.getCreatedAt(),o.getUpdatedAt());}
}
